import random
import struct
from typing import List

# Generator for a byte string with NULs intended for StringUtils::remove_null_terminating_chars
# The fuzzer stub takes FUZZ_PARAM_STR(), then injects a NUL at mid, appends NUL, 'A', NUL.
# We produce initial buffers that already explore cases like:
# - No NULs
# - Only trailing NULs
# - Only embedded NULs
# - Leading NULs
# - Repeated NUL runs
# - Interspersed ASCII and high-bytes
# - UTF-8-like sequences and random bytes
# Size limited to <= 4096 after fuzzer injections.

MAX_TOTAL = 4096

ASCII_SETS: List[bytes] = [
    b"",  # allow empty base (fuzzer will still inject NULs)
    b"OpenRGB",                       # plain ASCII
    b"\x00\x00\x00",                 # pure NULs
    b"A\x00B\x00C",                  # embedded NULs
    b"\x00LEAD",                      # leading NUL
    b"TRAIL\x00\x00",                 # trailing NULs
    b"MIX\x00ED\x00DATA\x00",        # mixed
    b"NULLS-ONLY-\x00\x00\x00\x00\x00",
    b"boundary-check",                # simple
]

UTF8_LIKE = [
    "✓", "é", "😊", "汉字", "Русский", "العربية", "हिन्दी", "日本語",
]


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _make_segment(r: random.Random) -> bytes:
    choice = r.randrange(8)
    if choice == 0:
        # ASCII chunk
        base = r.choice(ASCII_SETS)
        # maybe repeat
        return base * r.randint(1, 3)
    if choice == 1:
        # Random bytes with some probability of NULs
        n = r.randint(4, 64)
        b = bytearray(_rand_bytes(r, n))
        # sprinkle a few NULs
        for _ in range(r.randint(0, max(1, n // 8))):
            b[r.randrange(n)] = 0
        return bytes(b)
    if choice == 2:
        # Run of NULs
        return b"\x00" * r.randint(1, 32)
    if choice == 3:
        # Alternating printable and NUL
        length = r.randint(4, 64)
        out = bytearray()
        for i in range(length):
            if i % 2:
                out.append(0)
            else:
                out.append(r.randrange(32, 127))
        return bytes(out)
    if choice == 4:
        # UTF-8 like sequence (valid UTF-8 bytes), optionally interleaved with NULs
        s = r.choice(UTF8_LIKE) * r.randint(1, 8)
        b = bytearray(s.encode('utf-8'))
        if r.random() < 0.5:
            # insert some NULs between codepoints
            inserts = r.randint(1, min(5, len(b) + 1))
            for _ in range(inserts):
                pos = r.randrange(len(b) + 1)
                b[pos:pos] = b"\x00"
        return bytes(b)
    if choice == 5:
        # Structured pattern with sentinels and NUL runs
        parts = [b"HDR", b"\x00\x00", b"PAY", b"\x00", b"LOAD", b"\x00\x00\x00", b"END"]
        return b"".join(parts)
    if choice == 6:
        # High-bit bytes and control chars mixed with NULs
        n = r.randint(8, 48)
        out = bytearray()
        for _ in range(n):
            if r.random() < 0.2:
                out.append(0)
            else:
                out.append(r.randrange(128, 256) if r.random() < 0.5 else r.randrange(1, 32))
        return bytes(out)
    # choice == 7
    # Repeated token separated by NULs
    token = r.choice([b"RGB", b"ZONE", b"LED", b"MODE"]) 
    count = r.randint(2, 16)
    sep = b"\x00" * r.randint(1, 3)
    return sep.join([token] * count)


def _compose_buffer(r: random.Random) -> bytes:
    # Choose an overall scenario that steers the distribution
    scenario = r.randrange(7)
    chunks: List[bytes] = []

    if scenario == 0:
        # Mostly ASCII, a few NULs
        chunks.append(r.choice(ASCII_SETS))
        for _ in range(r.randint(1, 4)):
            chunks.append(_make_segment(r))
    elif scenario == 1:
        # Leading NULs then content
        chunks.append(b"\x00" * r.randint(1, 64))
        for _ in range(r.randint(2, 5)):
            chunks.append(_make_segment(r))
    elif scenario == 2:
        # Trailing NULs heavy
        for _ in range(r.randint(1, 4)):
            chunks.append(_make_segment(r))
        chunks.append(b"\x00" * r.randint(16, 256))
    elif scenario == 3:
        # Embedded alternating sequences
        for _ in range(r.randint(3, 8)):
            chunks.append(_make_segment(r))
    elif scenario == 4:
        # Short minimal strings (let stub inject mid/trailing NULs)
        chunks.append(r.choice([b"", b"A", b"AB", b"ABC"]))
    elif scenario == 5:
        # UTF-8-like block with NUL separators
        for _ in range(r.randint(2, 6)):
            chunks.append(_make_segment(r))
            chunks.append(b"\x00")
    else:
        # Random bytes bias, with occasional long NUL run inside
        chunks.append(_rand_bytes(r, r.randint(16, 128)))
        if r.random() < 0.8:
            chunks.append(b"\x00" * r.randint(8, 128))
        chunks.append(_rand_bytes(r, r.randint(16, 128)))

    buf = b"".join(chunks)

    # Ensure size leaves room for fuzzer's extra 3 bytes (NUL, 'A', NUL) without exceeding 4096
    # and the mid-position NUL overwrite does not increase length. Trim if needed.
    max_len = MAX_TOTAL - 3
    if len(buf) > max_len:
        buf = buf[:max_len]

    # Occasionally return exact edge sizes
    if r.random() < 0.1:
        edge = r.choice([0, 1, 2, 3, max_len])
        if edge <= len(buf):
            buf = buf[:edge]
        else:
            buf = buf + b"\x00" * (edge - len(buf))

    return buf


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Small randomization per call while remaining deterministic for the given seed
    # by consuming a few PRNG values before generation.
    warmups = r.randint(0, 5)
    for _ in range(warmups):
        r.random()
    buf = _compose_buffer(r)
    return buf
